stop(): void {
  this.abortController?.abort();
}

dispose(): void {
  this.abortController?.abort();
  this.unsubscribeLongTermMemory();
  this.listeners.clear();
}

export function classifyAttachment(
  file: Pick<FileDescriptor, 'name' | 'type'>,
): ChatAttachmentKind | null {
  const mediaType = file.type.toLowerCase();

  if (
    IMAGE_MEDIA_TYPES.has(mediaType) ||
    IMAGE_EXTENSIONS.has(extensionOf(file.name))
  ) {
    return 'image';
  }
  if (
    mediaType.startsWith('text/') ||
    TEXT_MEDIA_TYPES.has(mediaType) ||
    TEXT_EXTENSIONS.has(extensionOf(file.name))
  ) {
    return 'text';
  }

  return null;
}

const apiKey = process.env.DEEPSEEK_API_KEY?.trim();

if (!apiKey) {
  return jsonError(500, {
    code: 'configuration_error',
    message: 'DEEPSEEK_API_KEY не настроен. Добавьте токен в .env.local.',
  });
}

export const MAX_FACTS = 20;
export const MAX_FACT_KEY_LENGTH = 80;
export const MAX_FACT_VALUE_LENGTH = 500;

const IMAGE_MEDIA_TYPES = new Set([
  'image/jpeg',
  'image/png',
  'image/gif',
  'image/webp',
]);
